mapper.select:
SELECT item.id, item.student_id, item.goal_id, goal.standard_number, goal.goal_type, goal.category_code, category.label AS category_label, goal.goal_text, item.initial_level, item.current_level, item.phase, item.status FROM student_training_goal item JOIN training_goal goal ON goal.id = item.goal_id JOIN training_goal_category category ON category.code = goal.category_code WHERE item.student_id = #{studentId}
AND goal.goal_text LIKE CONCAT('%', #{keyword}, '%')
AND goal.category_code = #{categoryCode}
AND item.status = #{status}
ORDER BY category.display_order, item.id

SELECT id, standard_number, category_code, goal_text, goal_type, owner_student_id
FROM training_goal
WHERE id = #{id}

SELECT COUNT(*) > 0
FROM student_training_goal
WHERE student_id = #{studentId} AND goal_id = #{goalId}

mapper.update:
UPDATE student_training_goal
SET current_level = #{currentLevel}, phase = #{phase}, status = #{status}
WHERE id = #{id} AND student_id = #{studentId}

mapper.select:
SELECT selection.behavior_record_id AS record_id, option_row.code AS option_code, option_row.option_type, option_row.label, selection.custom_text FROM behavior_record_catalog_selection selection JOIN behavior_catalog_option option_row ON option_row.code = selection.option_code WHERE selection.behavior_record_id IN
#{recordId}
ORDER BY selection.behavior_record_id, option_row.option_type, option_row.display_order

SELECT log.id, log.student_goal_id, log.standard_number, log.goal_text,
       log.changed_by, log.changed_at, log.field_name, log.old_value, log.new_value
FROM training_goal_change_log log
JOIN student_training_goal stg ON stg.id = log.student_goal_id
WHERE log.standard_number = #{standardNumber} AND stg.student_id = #{studentId}
ORDER BY log.changed_at DESC LIMIT #{limit}

SELECT log.id, log.student_goal_id, log.standard_number, log.goal_text,
       log.changed_by, log.changed_at, log.field_name, log.old_value, log.new_value
FROM training_goal_change_log log
JOIN student_training_goal stg ON stg.id = log.student_goal_id
WHERE stg.student_id = #{studentId} AND log.changed_at >= #{since}
ORDER BY log.changed_at DESC LIMIT #{limit}
